import {coords} from './geo.js';
import {places} from './places.js';
import {artUse,foodArt} from './art.js';
export function pointsFor(stations){return stations.map((s,i)=>{if(coords[s.id])return coords[s.id].map(n=>n+70);let a=i-1,b=i+1;while(a>=0&&!coords[stations[a].id])a--;while(b<stations.length&&!coords[stations[b].id])b++;const start=a>=0?coords[stations[a].id]:[50,80],end=b<stations.length?coords[stations[b].id]:[910,510],t=(i-a)/(b-a);return [start[0]+(end[0]-start[0])*t+70,start[1]+(end[1]-start[1])*t+70];});}
export function pointAt(points,position){const i=Math.max(0,Math.min(points.length-1,Math.floor(position))),j=Math.min(i+1,points.length-1),t=Math.max(0,Math.min(1,position-i));return [points[i][0]+(points[j][0]-points[i][0])*t,points[i][1]+(points[j][1]-points[i][1])*t];}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function baseMap(){
 const roads=`M-100 490 280 140 640 460 1200 270M-100 610 390 60 1080 650M90 900 320 420 690-80M-80 100 1200 780M-100 320 480 530 900 30M60 820 600 350 1200 440`;
 const trees=Array.from({length:23},(_,i)=>{const x=410+(i*37)%155,y=290+(i*29)%100;return `<circle cx="${x}" cy="${y}" r="${5+i%4}" fill="var(--map-tree)" opacity=".5"/>`;}).join('');
 return `<defs><pattern id="map-blocks" width="79" height="61" patternTransform="rotate(-24)" patternUnits="userSpaceOnUse"><rect x="8" y="10" width="24" height="19" rx="3" fill="var(--map-building)"/><rect x="40" y="10" width="29" height="40" rx="3" fill="var(--map-building)"/><rect x="8" y="36" width="24" height="14" rx="2" fill="var(--map-building)"/><path d="M1 0v61M0 1h79" stroke="var(--map-street)" stroke-width="4"/></pattern><pattern id="map-grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M0 0h30v30" fill="none" stroke="var(--map-grid)" stroke-width=".6"/></pattern></defs><rect x="-2000" y="-2000" width="5100" height="4800" fill="var(--map-land)"/><g class="garden-basemap"><rect x="-2000" y="-2000" width="5100" height="4800" fill="url(#map-blocks)" opacity=".75"/><path d="M960-200C910 40 1015 182 927 307S851 436 903 523S828 701 880 980" fill="none" stroke="var(--map-water-edge)" stroke-width="57"/><path d="M960-200C910 40 1015 182 927 307S851 436 903 523S828 701 880 980" fill="none" stroke="var(--map-water)" stroke-width="45"/><path d="M${roads.slice(1)}" fill="none" stroke="var(--map-road-edge)" stroke-width="18" stroke-linejoin="round"/><path d="${roads}" fill="none" stroke="var(--map-road)" stroke-width="12" stroke-linejoin="round"/><path d="M478 287q65-64 124 4l-6 93-72 44-56-67z" fill="var(--map-park)" stroke="var(--map-water)" stroke-width="12"/><path d="M662 89q55-43 105 7l-4 66-74 8zM125 408q77-44 111 11l-24 47-94-6zM290 352l80-32 47 40-24 47-103-9z" fill="var(--map-park)"/>${trees}<path d="m904 289 42 13m-55 154 40-5" stroke="var(--map-road-edge)" stroke-width="17"/><path d="m904 289 42 13m-55 154 40-5" stroke="var(--map-road)" stroke-width="10"/></g><g class="blueprint-basemap"><rect x="-2000" y="-2000" width="5100" height="4800" fill="url(#map-grid)"/></g><g class="map-districts"><text x="175" y="268">新宿 <tspan>SHINJUKU</tspan></text><text x="239" y="633">渋谷 <tspan>SHIBUYA</tspan></text><text x="754" y="279">台東 <tspan>TAITO</tspan></text><text x="707" y="622">中央 <tspan>CHUO</tspan></text><text x="366" y="162">文京 <tspan>BUNKYO</tspan></text></g><text x="545" y="382" class="map-area-label" text-anchor="middle">皇居 · 고쿄</text>${artUse('palace',509,294,68)}<text x="950" y="440" class="river-label" transform="rotate(75 950 440)">SUMIDA RIVER · 隅田川</text>`;
}
export class JourneyMap {
 constructor(svg,{preview=false,onStation=()=>{},onInspect=()=>{}}={}){this.svg=svg;this.preview=preview;this.onStation=onStation;this.onInspect=onInspect;this.position=0;this.targetPosition=0;this.motionId=0;this.camera=null;this.cameraTarget=null;this.drag=null;this.hidden=false;this.follow=true;
  this.svg.addEventListener('pointerdown',e=>{if(this.preview||e.button!==0||e.target.closest('[role="button"]'))return;this.drag={x:e.clientX,y:e.clientY,view:[...this.cameraTarget],moved:false};svg.setPointerCapture(e.pointerId);});
  this.svg.addEventListener('pointermove',e=>{if(!this.drag)return;const r=svg.getBoundingClientRect(),dx=e.clientX-this.drag.x,dy=e.clientY-this.drag.y;if(Math.abs(dx)+Math.abs(dy)>4){this.drag.moved=true;this.follow=false;this.onInspect();}this.cameraTarget=[this.drag.view[0]-dx/r.width*this.camera[2],this.drag.view[1]-dy/r.height*this.camera[3],this.camera[2],this.camera[3]];this.wake();});
  const end=()=>this.drag=null;this.svg.addEventListener('pointerup',end);this.svg.addEventListener('pointercancel',end);
  this.resize=new ResizeObserver(()=>this.layout());this.resize.observe(svg);
 }
 build(stations,settings,{index=0,memory=false}={}){
  this.stations=stations;this.settings=settings;this.points=pointsFor(stations);this.index=index;this.memory=memory;this.follow=settings.follow;this.position=0;this.targetPosition=0;this.camera=null;this.cameraTarget=null;
  const prefix=this.preview?'preview':'game';let base=baseMap();for(const id of ['map-blocks','map-grid'])base=base.replaceAll(`id="${id}"`,`id="${prefix}-${id}"`).replaceAll(`url(#${id})`,`url(#${prefix}-${id})`);
  this.svg.innerHTML=base+`<g class="map-route"><polyline class="route-shadow" points="${this.points.map(p=>p.join(',')).join(' ')}"/><polyline class="route-main" points="${this.points.map(p=>p.join(',')).join(' ')}"/><polyline class="route-dashes" points="${this.points.map(p=>p.join(',')).join(' ')}"/></g><g class="poi-layer"></g><g class="station-layer"></g><g class="journey-train" aria-label="여행 열차"><circle class="train-halo" cy="2" r="19"/><g transform="translate(-27 -38)">${artUse('train',0,0,54)}</g></g>`;
  this.train=svgQuery(this.svg,'.journey-train');this.renderStations();this.renderPois();this.layout(true);this.wake();
 }
 renderStations(){if(!this.stations)return;const html=this.stations.map((s,i)=>{const [x,y]=this.points[i],hide=this.memory&&i>=this.index;return `<g role="button" tabindex="0" data-station="${i}" class="map-stop ${i<this.index?'arrived':''} ${i===this.index?'target':''}" aria-label="${hide?'숨겨진 역':escape(s.ko)} 역 정보"><circle cx="${x}" cy="${y}" r="${i===this.index?7:4.5}"/><text class="stop-label" x="${x}" y="${y+(i%2?-14:23)}" text-anchor="middle">${hide?'?':escape(s[this.settings.language])}</text></g>`;}).join('');svgQuery(this.svg,'.station-layer').innerHTML=html;
  this.svg.querySelectorAll('[data-station]').forEach(e=>{const click=()=>this.onStation(Number(e.dataset.station));e.onclick=click;e.onkeydown=event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();click();}};});this.svg.classList.toggle('hide-labels',!this.settings.labels);
 }
 renderPois(){if(!this.stations)return;const candidates=this.stations.map((s,i)=>({s,i,p:places[s.id]})).filter(x=>x.p);const html=candidates.filter((v,i)=>this.preview?i%3===0:i%2===0||v.s.id==='asakusa').map(({s,i,p},j)=>{
  const [x,y]=this.points[i],side=j%2?1:-1,px=x+side*43,py=y+(j%3===0?55:-59),food=this.settings.layer==='food';
  return `<g class="landmark-pin" role="button" tabindex="0" data-poi="${i}" aria-label="${escape(food?p.food:p.sight)}"><path d="M${x+side*8} ${y}L${px} ${py+15}" class="poi-leader"/><ellipse cx="${px}" cy="${py+17}" rx="25" ry="7" class="landmark-ground"/>${artUse(food?foodArt(p):p.icon,px-31,py-43,62)}<text x="${px}" y="${py+36}" text-anchor="middle" class="poi-label">${escape(food?p.food:p.sight)}</text>${this.settings.layer==='all'?`<g transform="translate(${px+19} ${py-9})"><circle r="13" class="food-badge"/>${artUse(foodArt(p),-13,-15,26)}</g>`:''}</g>`;
 }).join('');svgQuery(this.svg,'.poi-layer').innerHTML=html;svgQuery(this.svg,'.poi-layer').style.display=this.settings.landmarks?'':'none';this.svg.querySelectorAll('[data-poi]').forEach(e=>{const click=()=>this.onStation(Number(e.dataset.poi));e.onclick=click;e.onkeydown=event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();click();}};});
 }
 update({index=this.index,settings=this.settings}={}){this.index=index;this.settings=settings;this.follow=settings.follow;this.svg.dataset.skin=settings.skin;this.renderStations();this.renderPois();this.layout();}
 layout(immediate=false){if(!this.points)return;const r=this.svg.getBoundingClientRect();if(!r.width||!r.height)return;if(this.preview){this.svg.setAttribute('viewBox','0 0 1100 740');return;}const baseWidth=r.width<620?650:1100,w=baseWidth/(this.settings.zoom/100),h=w/(r.width/r.height),p=pointAt(this.points,this.position);if(!this.camera||this.follow)this.cameraTarget=[p[0]-w*.53,p[1]-h*.40,w,h];else this.cameraTarget=[this.cameraTarget[0]+(this.cameraTarget[2]-w)/2,this.cameraTarget[1]+(this.cameraTarget[3]-h)/2,w,h];if(immediate||!this.camera)this.camera=[...this.cameraTarget];this.wake();}
 moveTo(position,{instant=false}={}){this.targetPosition=Math.max(0,Math.min(position,this.points.length-1));if(instant)this.position=this.targetPosition;this.wake();}
 inspect(index){if(!this.points[index])return;this.follow=false;const w=this.camera[2],h=this.camera[3],p=this.points[index];this.cameraTarget=[p[0]-w*.53,p[1]-h*.4,w,h];this.wake();}
 wake(){if(!this.motionId)this.motionId=requestAnimationFrame(()=>this.frame());}
 frame(){this.motionId=0;if(!this.points)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,blend=reduced?1:.13;this.position+=(this.targetPosition-this.position)*blend;const p=pointAt(this.points,this.position);this.train?.setAttribute('transform',`translate(${p[0]} ${p[1]})`);
  if(!this.preview&&this.camera){if(this.follow){const w=this.cameraTarget[2],h=this.cameraTarget[3];this.cameraTarget=[p[0]-w*.53,p[1]-h*.4,w,h];}this.camera=this.camera.map((n,i)=>n+(this.cameraTarget[i]-n)*(reduced?1:.1));this.svg.setAttribute('viewBox',this.camera.join(' '));}
  if(Math.abs(this.targetPosition-this.position)>.001||this.camera?.some((n,i)=>Math.abs(n-this.cameraTarget[i])>.02))this.wake();
 }
 destroy(){cancelAnimationFrame(this.motionId);this.resize.disconnect();}
}
function svgQuery(svg,s){return svg.querySelector(s);}
